<template>
  <div class="ad-root">
    <!-- ── HERO ──────────────────────────────────────────────────────── -->
    <header class="ad-hero">
      <div class="ad-hero__bg">
        <div class="ad-hero__grid"></div>
        <div class="ad-hero__glow"></div>
      </div>
      <div class="ad-hero__inner">
        <div class="ad-hero__content">
          <v-avatar size="72" style="flex-shrink:0; background:linear-gradient(135deg,#0d9488,#14b8a6); border:3px solid rgba(255,255,255,0.15);">
              <span class="white--text text-h5 font-weight-bold">{{ initials }}</span>
            </v-avatar>
          <div>
            <h1 class="ad-hero__title">Welcome, {{ firstName }}</h1>
            <p class="ad-hero__sub">
              Manage your applications, update your profile, and browse open
              positions — all in one place.
            </p>
          </div>
        </div>
      </div>
    </header>

    <!-- ── APP ICON GRID ─────────────────────────────────────────────── -->
    <main class="ad-app-grid">
      <!-- My Applications -->
      <div class="ad-app-item" @click="goToApplications">
        <div class="ad-app-icon" style="background:linear-gradient(135deg,#3b82f6,#1d4ed8);">
          <v-icon size="52" color="white">mdi-file-document-multiple-outline</v-icon>
        </div>
        <div class="ad-app-label">My Applications</div>
        <div class="ad-app-desc">Track status of positions you applied for</div>
      </div>

      <!-- My Profile -->
      <div class="ad-app-item" :class="{ 'ad-app-item--disabled': !profileId }" @click="goToProfile">
        <div class="ad-app-icon" style="background:linear-gradient(135deg,#0d9488,#14b8a6);">
          <v-icon size="52" color="white">mdi-account-outline</v-icon>
        </div>
        <div class="ad-app-label">My Profile</div>
        <div class="ad-app-desc">{{ practitionerId ? "View your HR profile" : "Update your personal info" }}</div>
      </div>

      <!-- Advertised Positions -->
      <div class="ad-app-item" @click="goToPositions">
        <div class="ad-app-icon" style="background:linear-gradient(135deg,#f59e0b,#d97706);">
          <v-icon size="52" color="white">mdi-briefcase-outline</v-icon>
        </div>
        <div class="ad-app-label">Open Positions</div>
        <div class="ad-app-desc">Browse vacancies and apply</div>
      </div>
    </main>
  </div>
</template>

<script>
export default {
  name: "ApplicantDashboard",

  computed: {
    userResource() {
      return this.$store.state?.user?.obj?.resource;
    },

    displayName() {
      return (
        this.userResource?.name?.[0]?.text ||
        this.userResource?.telecom?.find((t) => t.system === "email")?.value ||
        "Applicant"
      );
    },

    firstName() {
      const full = this.displayName;
      return full.split(" ")[0] || full;
    },

    initials() {
      return this.displayName
        .split(" ")
        .slice(0, 2)
        .map((w) => w[0])
        .join("")
        .toUpperCase();
    },

    practitionerId() {
      const ref = this.userResource?.extension?.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
      )?.valueReference?.reference;
      return ref ? ref.split("/")[1] : null;
    },

    profileId() {
      if (this.practitionerId) return this.practitionerId;
      const ref = this.userResource?.extension?.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-external-applicant-reference",
      )?.valueReference?.reference;
      return ref ? ref.split("/")[1] : null;
    },
  },

  methods: {
    goToApplications() {
      this.$router.push({
        path: "/custom/my-applications",
        query: { path: "/lesotho/components/recruitment" },
      });
    },

    goToProfile() {
      if (!this.profileId) return;
      if (this.practitionerId) {
        this.$router.push(`/resource/view/practitioner/${this.practitionerId}`);
        return;
      }
      this.$router.push({
        path: "/custom/applicant-profile",
        query: {
          path: "/lesotho/components/recruitment",
          id: this.profileId,
        },
      });
    },

    goToPositions() {
      this.$router.push({
        path: "/custom/advertised-positions",
        query: { path: "/lesotho/components/recruitment" },
      });
    },
  },
};
</script>

